section.code_example:
# Create dimension
vDimName = 'Product';
IF(DimensionExists(vDimName) = 0);
    DimensionCreate(vDimName);
ENDIF;
DimensionDeleteAllElements(vDimName);

# Insert dimension elements
DimensionElementInsert(vDimName, '', 'Phones', 'S');
DimensionElementInsert(vDimName, '', 'Laptops', 'S');
DimensionElementInsert(vDimName, '', 'Tablets', 'S');

# Create attributes
AttrInsert(vDimName, '', 'category', 'A');
AttrInsert(vDimName, '', 'price', 'N');

# Set attribute values
AttrPutS('Electronics', vDimName, 'Phones', 'category');
AttrPutN(599, vDimName, 'Phones', 'price');

# Create cube
vCubeName = 'Sales';
IF(CubeExists(vCubeName) = 0);
    CubeCreate(vCubeName, 'Product', 'Region', 'Time', 'Measures');
ENDIF;

# Load fact data
CellPutN(15000, vCubeName, 'Phones', 'North', 'Jan', 'revenue');
CellPutN(250, vCubeName, 'Phones', 'North', 'Jan', 'units_sold');
CellPutN(12500, vCubeName, 'Laptops', 'South', 'Jan', 'revenue');
CellPutN(125, vCubeName, 'Laptops', 'South', 'Jan', 'units_sold');
